import json
from lib import *
R = J('r131'); q = R['quirk']; cl = R['calls']; cm = R['cmp']; ra = R['rep_a']; rb = R['rep_b']
KV = lambda items, hl=(): {'items': items, 'hl': list(hl)}
def fl(nodes, cur=(), done=(), mark=()): return {'nodes': nodes, 'cur': list(cur), 'done': list(done), 'mark': list(mark)}
def tl(lines, cur=(), mark=()): return {'lines': lines, 'cur': list(cur), 'mark': list(mark)}
def bars(items, mx, cur=(), mark=(), done=()): return {'items': items, 'max': mx, 'cur': list(cur), 'mark': list(mark), 'done': list(done)}
steps = [
    step("配置里写 rename-command FLUSHALL \"\"、rename-command KEYS \"\"、rename-command CONFIG CFG_a83f。调用 FLUSHALL → ERR unknown command 'FLUSHALL';KEYS *、CONFIG GET dir 同样是 unknown command;CFG_a83f GET maxmemory 正常返回。禁用 = 改名为空串,改名 = 换成别人猜不到的名字。", t=tl([f"{k:<24} {v[:70]}" for k, v in cl.items()], mark=[0, 1, 2], cur=[3]), kv=KV([['禁用', '改名为空串'], ['改名', '换成一个别人猜不到的名字']], ['禁用'])),
    step(f"一个我没有查明原因的怪现象:改名为 K_ab7 的 KEYS,在同一连接上「紧跟在 K_ab7 之后」的 KEYS * 居然也能执行({q['seq1'][1][1]});中间插一条 DBSIZE,再发 KEYS * 又是 unknown command。新连接直接 KEYS * 仍是 unknown;被禁用为空串的 FLUSHALL 在这条连接上照样 unknown。不知道新名字的人碰不到它,但它说明 rename-command 不是一道严密的边界。", t=tl([f"{c_:<10} → {r_}" for c_, r_ in q['seq1']] + [f"(新连接){'KEYS *':<10} → {q['fresh'][:40]}"], mark=[3, 4], cur=[1]), kv=KV([['条件', '同一连接、紧跟在新名字之后'], ['原因', '没有查明']], ['条件'])),
    step(f"改名之后的元数据:COMMAND LIST 里已经没有 flushall、keys、cfg_a83f,但仍有 config 和 config|get;COMMAND INFO cfg_a83f 返回的条目名字仍是 config;INFO commandstats 里记的仍是 cmdstat_config|get(原名)。运行时 CONFIG SET rename-command → {R['runtime_rename'][:60]};CONFIG REWRITE 会保留 redis.conf 里的三行 rename-command。", t=tl([f"COMMAND LIST 含 {k}: {v}" for k, v in R['names'].items()] + [f"COMMAND INFO flushall / cfg_a83f / config → {R['cinfo']}", f"commandstats: {R['cstats']}"], cur=[0, 1, 2, 3, 4, 5]), kv=KV([['统计里的名字', '原名(config|get)']], ['统计里的名字'])),
    step(f"和 ACL(-flushall)对比:各执行 3 次被禁的 FLUSHALL。rename 节点:acl_access_denied_cmd = {cm['rename']['acl_cmd']},ACL LOG {cm['rename']['acl_log']} 条,错误类型 ERR unknown command。ACL 节点:acl_access_denied_cmd = {cm['acl']['acl_cmd']},ACL LOG {cm['acl']['acl_log']} 条(count 累加),错误类型 NOPERM。ACL 让「谁在试」留下痕迹;rename 只回一句 unknown command。", b=bars([['rename:acl_access_denied_cmd', cm['rename']['acl_cmd'], str(cm['rename']['acl_cmd'])], ['ACL:acl_access_denied_cmd', cm['acl']['acl_cmd'], str(cm['acl']['acl_cmd'])], ['rename:ACL LOG 条数', cm['rename']['acl_log'], str(cm['rename']['acl_log'])], ['ACL:ACL LOG 条数', cm['acl']['acl_log'], str(cm['acl']['acl_log'])]], 4, mark=[0, 2], done=[1, 3]), kv=KV([['rename 的回复', cm['rename_reply']], ['ACL 的回复', cm['acl_reply'][:60]]], ['ACL 的回复'])),
    step(f"改名与复制/AOF(主库把 FLUSHALL 改成 FA9x,从库没改):主库执行 FA9x → OK,主库 DBSIZE = {ra['dbsize'][0]};从库 DBSIZE 仍是 {ra['dbsize'][1]},master_link_status = {ra['link']}。AOF 里记的清库命令名是 {ra['aof']}。从库日志:「This replica is sending an error to its master: unknown command 'FA9x'」。主从悄悄不一致,而链路显示正常。", n=fl([['主库 FA9x', 'DBSIZE 0'], ['AOF', "记录 'FA9x'"], ['从库(未改名)', 'unknown command,DBSIZE 仍 20'], ['master_link_status', 'up']], mark=[2], done=[0, 3]), kv=KV([['主库 / 从库 DBSIZE', f"{ra['dbsize'][0]} / {ra['dbsize'][1]}"], ['link', ra['link']]], ['主库 / 从库 DBSIZE'])),
    step(f"反过来:主库正常、从库把 FLUSHALL 禁用。主库 FLUSHALL 后,主库 DBSIZE = {rb['dbsize'][0]},从库仍是 {rb['dbsize'][1]},link = {rb['link']};1.5 秒后偏移量主从都是 {rb['later']['offs'][0]}(相同),数据仍然不一致。复制偏移量一致不代表数据一致。", n=fl([['主库 FLUSHALL', 'DBSIZE 0'], ['从库(FLUSHALL 被禁)', 'CRITICAL 日志,DBSIZE 仍 20'], ['repl offset', '主从相同']], mark=[1], done=[0, 2]), kv=KV([['主库 / 从库 DBSIZE', f"{rb['dbsize'][0]} / {rb['dbsize'][1]}"], ['repl offset', f"{rb['later']['offs'][0]} = {rb['later']['offs'][1]}"]], ['主库 / 从库 DBSIZE'])),
]
A = dict(
    n=131, series='redis', tags='Redis,安全,rename-command,ACL,复制,真实验证,动画演示',
    desc=f'rename-command 实测:禁用或改名后是 unknown command;统计与 COMMAND INFO 仍用原名;运行时不能改;与 ACL 相比被拒的尝试不留痕迹(ACL LOG {cm["rename"]["acl_log"]} 条 vs {cm["acl"]["acl_log"]} 条);主从改名不一致时,复制与 AOF 悄悄分叉——主库 DBSIZE {ra["dbsize"][0]},从库 {ra["dbsize"][1]},链路仍显示 up。',
    lead='rename-command 是老办法:把危险命令改成别人猜不到的名字,或者直接禁用。ACL 出现之后,还该不该用它?这篇实测它的行为、跟 ACL 的可观测性差异,以及一个更要命的地方:改名之后复制和 AOF 是怎么处理的。',
    facts=[('unknown command', '禁用 / 改名后原命令报 unknown command;运行时不能改,只能写配置文件重启'), (f'{cm["rename"]["acl_log"]} vs {cm["acl"]["acl_log"]}', '被禁命令连续尝试 3 次后,rename 方案的 ACL LOG 条数 vs ACL 方案(count 累加)'), (f'{ra["dbsize"][0]} vs {ra["dbsize"][1]}', '主从 rename 配置不一致时,主库 FLUSHALL 之后主库 / 从库的 DBSIZE;链路仍显示 up、偏移量一致')],
    body=[
        sec('改名与禁用', '', term('', blk('r131', 1)), '<p>写在配置文件里的 <code>rename-command 原名 新名</code>,新名为空串就是禁用。之后原名报 <code>unknown command</code>,改名后的名字才能用。</p>'),
        sec('元数据与运行时', '', term('', blk('r131', 2)), '<p>改名后 <code>COMMAND LIST</code> 不再列出原名(也没有新名),但 <code>config</code>、<code>config|get</code> 这类名字还在;统计里仍记原名。<code>CONFIG SET rename-command</code> 不被支持,只能改配置文件后重启;<code>CONFIG REWRITE</code> 会保留这些行。</p>'),
        sec('一个没查明原因的怪现象', '', term('', blk('r131', 6)), '<p>同一连接上,紧跟在成功调用「新名字」之后的「原名字」也能执行;中间隔一条别的命令就又是 <code>unknown command</code>。新连接、以及被禁用为空串的命令都不受影响。这不能让不知道新名字的人得到什么,但说明 <code>rename-command</code> 不是一道严密的边界:别把它当唯一的防线,也别用「原名字报 unknown command」当审计依据。原因没有查源码,不做解释。</p>'),
        sec('对比 ACL:能不能看见谁在试', '', term('', blk('r131', 3)), '<p>ACL 拒绝会被计入 <code>acl_access_denied_cmd</code> 并在 <code>ACL LOG</code> 里留下一条(第 125 篇);rename 后的 <code>unknown command</code> 只有一个通用的错误类型 <code>ERR</code>。要在被人试探时收到信号,ACL 更合适。另外 ACL 可以按用户区分,rename 是全局的。</p>'),
        sec('改名对复制和 AOF 的影响', '', term('', blk('r131', 4)), '<p>主库把 <code>FLUSHALL</code> 改名为 <code>FA9x</code>、从库没改:主库执行后 AOF 里记录的就是 <code>FA9x</code>,复制流里同样是它,从库不认识,只在日志里说 <code>unknown command</code>。结果是数据分叉,而 <code>master_link_status</code> 仍是 <code>up</code>。</p>', term('', blk('r131', 5)), '<p>反过来从库把 <code>FLUSHALL</code> 禁用也一样:主库清了,从库没清,日志里是 <code>== CRITICAL ==</code> 一行。两种情形下复制偏移量主从相同——偏移量一致不能当作数据一致的证据。</p>'),
        sec('怎么选', '', '<ul><li>要按用户区分、要审计、要能在线调整 → <b>ACL</b>(<code>-@dangerous</code> 或按命令禁)。</li><li>确实要用 rename → <b>所有节点(主、从、以及故障转移后可能成为主库的节点)的 rename 配置必须一致</b>,并且要在上线前实测复制。本文只测了两种「不一致」的情形,没有测「完全一致」的配置在复制与 AOF 重放下是否一切正常。</li></ul>'),
        sec('分步演示:rename-command 的每个后果', '', demo('rename-command', [('t', 'term', '输出'), ('b', 'bars', '对比'), ('n', 'flow', '复制'), ('kv', 'kv', '要点')], steps, '本步的对象')),
    ],
    refs=[ENV_R + '。所有改名只发生在我自己的临时实例上', '没有验证:主从 rename 配置完全一致时的复制与 AOF 重放、Sentinel / Cluster 对改名命令的处理、redis-cli 与客户端库对改名的兼容(如 redis-cli --cluster 使用的命令)、rename-command 在 Redis 8 之前版本的行为、上面「紧跟新名字之后原名可执行」现象的原因'],
)
